"""Read-only N2 report derivative, outside the frozen scientific producer set."""
import json
from pathlib import Path
H=Path(__file__).resolve().parent/'N2';O=H/'results'
def f(x):return f'{x:.8f}'
def interval(r):return f"{f(r['mean'])} [{f(r['ci95'][0])}, {f(r['ci95'][1])}]"
def main():
    summary=json.loads((O/'summary.json').read_text());verification=json.loads((O/'separate_verification.json').read_text());extension=json.loads((O/'continuation_verification.json').read_text());assert len(summary['conditions'])==len(verification['conditions'])==4 and summary['original_resource_gate_failed'] is True
    lines=['# N2 — exact policy-conditioned belief benchmark','','Status: self-checked (Codex), **pending external implementation/results audit**. New result packet remains local. M16 conditional deterministic/matched-bid proof was externally checked by Claude on 2026-11-17; that proof verdict does not validate this execution.','','## Held-out primary comparison','','Positive net-minus-BI means the learned factorized joint is worse. Each fixed fit is evaluated over the entire reached population in its held-out own-hand split. Intervals below are t95% over five paired optimization seeds only, not sampling CIs over chance deals/hands or a second independent test population. Small conditions are descriptive controls.','','|Condition|Reached test hands|Private test keys|Exact decision-world weight|Uniform KL|Soft-BI KL|Hard-bid KL|Net − soft-BI, n=5 fits, t95% CI|','|---|---:|---:|---:|---:|---:|---:|---|']
    for result in summary['conditions']:
        q=result['summaries']['test'];lines.append('|'+ '|'.join([result['condition'],str(q['n_reached_own_hands']),str(q['n_private_keys']),str(q['exact_reach_weight']),f(q['uniform_KL']),f(q['BI_KL']),f(q['hard_bid_KL']),interval(q['primary_net_minus_BI'])])+'|')
    lines+=['','All baseline entries are deterministic complete-population mean joint KL values in nats, computed with floating logarithms of exact support counts/integer bid weights. They do not receive sampling intervals. The net has five individual models rather than a post-hoc pooled primary ensemble.','','## All conditions and nulls retained','','|Condition|Split|Net − soft-BI, n=5 fits, t95% CI|Net share of uniform KL removed, n=5 fits, t95% CI|','|---|---|---|---|']
    for result in summary['conditions']:
        for split,q in result['summaries'].items():
            share=q['share_uniform_KL_removed'].get('net_seed_summary');lines.append(f"|{result['condition']}|{split}|{interval(q['primary_net_minus_BI'])}|{interval(share) if share else 'undefined: zero uniform KL'}|")
    lines+=['','All/train/validation rows are descriptive, not additional replications. Shares may be negative, are not additive, and are not a game-score fraction. Raw capacity-factor card log loss is separately saved and must not be confused with constrained-joint marginal log loss. Full per-seed KL, every raw key/chance support and model-selection candidate are retained.','','## Selection and provenance','','|Condition|Selected epochs (five fits)|Selected blends (five fits)|','|---|---|---|']
    for result in summary['conditions']:
        r=json.loads((O/result['condition']/'models/frozen_models.json').read_text());models=r['models'];lines.append(f"|{result['condition']}|{', '.join(str(v['selected_epoch']) for v in models)}|{', '.join(str(v['alpha']) for v in models)}|")
    lines+=['','At most30000training keys and4000validation keys per condition, selected by fixed SHA order within disjoint own-hand partitions; test uses every reached key. All/train summaries include uncapped keys as descriptive evaluations, not claims of full-key training. Fixed20epochs and five shared fit seeds; selection among checkpoints/blends uses validation card-marginal loss, not held-out joint KL. Thus these are selected belief pipelines, not an isolated architecture or joint-KL training comparison. Fixed SHA own-hand splits share latent deals across actor observations and have few distinct test hands. Seed intervals exclude hand-split uncertainty.','','Original scientific source commit: `1c0c7192f65464b79afa7a525e121f76543218c1`; fingerprint `7c7ba88609951b1b6a4be672984bf7adc3dc1bc7ababaeff7afa5d9ab10173b7`. The original three-hour forecast **failed before model/outcome generation**; original failed gate and scope-failure receipt remain unchanged. Resource-only continuation source commit `ba6505d43fa41e1c6a2e00d3d6ed5abe32c405dc` predeclared at most two further three-hour windows, preserving all scientific sources, counts, seeds and original pilot. Additional windows actually used: '+str(extension['additional_windows'])+'. This is an explicit resource-budget amendment, not a successful original gate.','','## Separate checks and limits','','The verifier checks every saved raw world/label/grouping, deterministic matched-bid support premise, every model selection and all reported CIs. A fresh manual rules/posterior/normalizer path covers all small infosets and64fixed large contexts per condition; it is not a second complete enumeration of every large posterior. Existing policy functions are reused as the profile definition. Resource-source and scientific-source manifests are checked separately.','','The benchmark concerns an all-dealt tiny game, fixed private TA play and matched deterministic bids, with every pre-play observation including forced moves. It is neither the M1 root relaxation nor a 52-card/game-score benchmark. Summary features and a normalized product family may lose history/dependence information. Finite epoch/blend grids may select boundaries and do not bracket an optimum. Do not attribute errors solely to optimization or neural capacity. N1 uses another game/profile, stock and a different predictive metric; comparisons between N1 and N2 are descriptive, not a controlled scaling effect.','','Windows I/O extension: first continuation failed replacing NT epoch2checkpoint; epoch1 and original traceback/tmp retained. Source-only adapter1d4eafb8e2652175288725e825484fe1ebbc8402 reads only resume checkpoints into memory-backed NPZ objects (identical arrays/API) and retries result-file PermissionError for at most5seconds. This prevents the identified resume file-handle self-lock, but first-error cause is unestablished. Second/final preallocated continuation uses this explicit runtime adapter; no frozen science/scheduler source changed. Include its manifest and separate provenance receipt in any future release.','','No publication release is implied by this report.']
    (H/'RESULTS.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');print('Wrote N2/RESULTS.md from completed, separately checked saved packet')
if __name__=='__main__':main()
